const cfg = $('Settings').first().json;
const ships = $('1. Find Geneva Candidates').all().map(i => i.json).filter(s => s && s.id);
const moves = $('2. Read Shipment Moves').all().map(i => i.json).filter(m => m && m.id);
const lines = $('3. Read Order Lines').all().map(i => i.json).filter(l => l && l.id);
const existing = $('4. Read Existing Personalisation').all().map(i => i.json).filter(o => o && o.id);

// Fulfil caps a page at 500. Hitting the cap means the read was truncated and every
// decision below would be made on partial data. Fail loudly rather than write wrongly.
const PAGE_CAP = 500;
if (moves.length >= PAGE_CAP) throw new Error('Truncated: stock.move hit the 500-row page cap. Lower lookbackDays.');
if (lines.length >= PAGE_CAP) throw new Error('Truncated: sale.line hit the 500-row page cap. Lower lookbackDays.');
if (existing.length >= PAGE_CAP) throw new Error('Truncated: sale.line.option hit the 500-row page cap. Lower lookbackDays.');

const customCodes = (cfg.customLogoCodes || []).map(c => String(c).toUpperCase());
const isCustomLogo = code => !!code && customCodes.includes(String(code).toUpperCase());
const SENT_STATES = ['sent', 'sending_in_progress', 'edi_document_created', 'waiting_cancellation', 'cancelled', 'cancellation_error'];

const movesById = new Map(moves.map(m => [m.id, m]));
const linesById = new Map(lines.map(l => [l.id, l]));
const linesBySale = new Map();
for (const l of lines) {
  if (!linesBySale.has(l.sale)) linesBySale.set(l.sale, []);
  linesBySale.get(l.sale).push(l);
}
const valueByLine = new Map();
for (const o of existing) {
  const v = o.value_string != null ? o.value_string : o.value;
  if (v != null && String(v).trim() !== '') valueByLine.set(o.line, String(v));
}

const out = [];
for (const s of ships) {
  const saleIds = s.sales || [];
  const orderLines = saleIds.flatMap(id => linesBySale.get(id) || []);
  const orderHasCustomLogo = orderLines.some(l => isCustomLogo(l['product.code']));

  const shipmentLineIds = [...new Set((s.outgoing_moves || [])
    .map(id => movesById.get(id))
    .filter(Boolean)
    .map(m => (typeof m.origin === 'string' && m.origin.startsWith('sale.line,')) ? Number(m.origin.split(',')[1]) : null)
    .filter(id => id !== null && !Number.isNaN(id)))];

  const targetLines = shipmentLineIds
    .map(id => linesById.get(id))
    .filter(Boolean)
    .filter(l => l.type === 'line')
    .filter(l => l['product.type'] === 'goods')
    .filter(l => !isCustomLogo(l['product.code']))
    .filter(l => Number(l.quantity) > 0);

  const linesNeedingOption = targetLines.filter(l => !valueByLine.has(l.id));
  const keptExistingValues = targetLines.filter(l => valueByLine.has(l.id))
    .map(l => ({ line: l.id, sku: l['product.code'], existingValue: valueByLine.get(l.id) }));

  const carrierOk = s.carrier === cfg.carrierId && s.carrier_service === cfg.carrierServiceId;
  const alreadySent = SENT_STATES.includes(s.tpl_status);
  const createdAt = (s.created_at && s.created_at.iso_string) ? s.created_at.iso_string.slice(0, 10) : null;
  const serviceName = s['carrier_service.rec_name'] || null;

  let action, reason;
  if (!orderHasCustomLogo) {
    action = 'skip';
    reason = 'No CUSTOM-LOGO line on the order';
  } else if (alreadySent) {
    // Once G10 has the shipment, writing to it changes nothing they will see.
    // Never write. Either it went out correctly, or ops has to fix it at the 3PL.
    if (carrierOk) {
      action = 'skip';
      reason = 'Already sent to the 3PL on ROUTE, nothing to do';
    } else {
      action = 'alert';
      reason = 'Already sent to the 3PL on ' + (s.carrier_service == null ? 'no service' : 'service ' + (serviceName || s.carrier_service)) + ', ops must fix this one with G10 directly';
    }
  } else if (carrierOk && linesNeedingOption.length === 0) {
    action = 'skip';
    reason = 'Already correct';
  } else {
    action = 'fix';
    reason = [carrierOk ? null : 'set carrier G10 / service ROUTE', linesNeedingOption.length ? linesNeedingOption.length + ' line(s) need Personalisation' : null].filter(Boolean).join(' + ');
  }

  out.push({ json: {
    action,
    reason,
    shipmentId: s.id,
    number: s.number,
    state: s.state,
    tplStatus: s.tpl_status,
    onHold: s.on_hold,
    orderNumbers: s.order_numbers,
    createdAt,
    company: s.company || cfg.companyId,
    saleIds,
    orderHasCustomLogo,
    currentCarrier: s.carrier,
    currentCarrierName: s['carrier.rec_name'] || null,
    currentService: s.carrier_service,
    currentServiceName: serviceName,
    targetCarrier: cfg.carrierId,
    targetService: cfg.carrierServiceId,
    carrierOk,
    alreadySent,
    keptExistingValues,
    targetLineIds: targetLines.map(l => l.id),
    optionsToCreate: linesNeedingOption.map(l => ({ line: l.id, option: cfg.personalisationOptionId, value_string: cfg.personalisationValue, sku: l['product.code'] }))
  }});
}
return out;

const cfg = $('Settings').first().json;
const planned = $('5. Decide Actions').all().map(i => i.json);
const fixes = planned.filter(p => p.action === 'fix');

// Inside a splitInBatches loop, $('Node').all() returns ONLY the last run.
// Walk every run index so the summary sees every shipment, not just the final one.
function allRuns(nodeName) {
  const out = [];
  for (let r = 0; r < 500; r++) {
    let items;
    try { items = $(nodeName).all(0, r); } catch (e) { break; }
    if (!items || items.length === 0) break;
    for (const it of items) if (it && it.json && it.json.id) out.push(it.json);
  }
  return out;
}

const verifiedCarrier = allRuns('12. Verify Carrier + Service');
const verifiedOptions = allRuns('13. Verify Personalisation');

const optionValueByLine = new Map(verifiedOptions.map(o => [o.line, o.value_string]));
const carrierById = new Map(verifiedCarrier.map(s => [s.id, s]));

const perShipment = fixes.map(f => {
  const after = carrierById.get(f.shipmentId) || null;
  const expectedLines = f.targetLineIds || [];
  const missing = expectedLines.filter(id => {
    const v = optionValueByLine.get(id);
    return v == null || String(v).trim() === '';
  });
  return {
    number: f.number,
    shipmentId: f.shipmentId,
    orderNumbers: f.orderNumbers,
    plannedReason: f.reason,
    carrierAfter: after ? after['carrier.rec_name'] : null,
    serviceAfter: after ? after['carrier_service.rec_name'] : null,
    carrierVerified: !!after && after.carrier === cfg.carrierId && after.carrier_service === cfg.carrierServiceId,
    linesExpected: expectedLines.length,
    linesWithPersonalisation: expectedLines.length - missing.length,
    linesMissingPersonalisation: missing,
    personalisationVerified: missing.length === 0,
    existingValuesKept: f.keptExistingValues || []
  };
});

const failures = perShipment.filter(p => !p.carrierVerified || !p.personalisationVerified);

return [{ json: {
  tenant: cfg.tenant,
  dryRun: false,
  ranAt: new Date().toISOString(),
  executionId: $execution.id,
  candidatesScanned: planned.length,
  shipmentsFixed: fixes.length,
  shipmentsSkipped: planned.filter(p => p.action === 'skip').length,
  shipmentsNeedingOpsFix: planned.filter(p => p.action === 'alert').length,
  allVerified: failures.length === 0,
  verificationFailures: failures,
  perShipment
}}];

const cfg = $('Settings').first().json;
const stuck = $input.all().map(i => i.json);
const isTest = cfg.testBanner === true;

const esc = v => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const serviceLabel = s => {
  if (s.currentService == null) return 'none set';
  return (s.currentServiceName ? esc(s.currentServiceName) : 'unknown') + ' (' + s.currentService + ')';
};
const carrierLabel = s => s.currentCarrier == null ? 'none set' : (s.currentCarrierName ? esc(s.currentCarrierName) : 'id ' + s.currentCarrier);

const rows = stuck.map(s => '<tr>' +
  '<td>' + esc(s.number) + '</td>' +
  '<td>' + esc(s.orderNumbers || '') + '</td>' +
  '<td>' + esc(s.createdAt || '') + '</td>' +
  '<td>' + carrierLabel(s) + '</td>' +
  '<td>' + serviceLabel(s) + '</td>' +
  '<td>' + esc(s.tplStatus) + '</td>' +
  '</tr>').join('');

const banner = isTest
  ? '<p style="background:#fff3cd;border:2px solid #e0a800;padding:12px;font-family:sans-serif">' +
    '<strong>THIS IS A TEST. No action needed.</strong><br>' +
    'Sent from the Fulfil <strong>sandbox</strong> to check the alert reaches everyone on the list. ' +
    'The shipment below is not a real custom-logo order, it was forced into the test deliberately. ' +
    'Please ignore and delete.</p>'
  : '';

const html = banner +
  '<p>These US Geneva custom-logo shipments went to the 3PL without carrier service ROUTE (656). ' +
  'n8n has not touched them and will not, because G10 already has the shipment. They need correcting with G10 directly.</p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">' +
  '<tr><th>Shipment</th><th>Order</th><th>Created</th><th>Carrier</th><th>Service</th><th>3PL status</th></tr>' +
  rows + '</table>' +
  '<p style="color:#666;font-size:12px">Tenant: ' + esc(cfg.tenant) + '. Workflow \"CUSTOM-LOGO Geneva routing\", execution ' + $execution.id + '. ' +
  'Search the shipment number in Fulfil to open it.</p>';

const subject = (isTest ? '[TEST - please ignore] ' : '') +
  'CUSTOM-LOGO: ' + stuck.length + ' Geneva shipment' + (stuck.length === 1 ? '' : 's') + ' sent to G10 without ROUTE';

return [{ json: { count: stuck.length, subject, html, shipments: stuck.map(s => s.number) } }];

const cfg = $('Settings').first().json;
const planned = $input.all().map(i => i.json);
const worthReporting = planned.filter(p => p.action === 'fix' || p.action === 'alert').length;
if (worthReporting === 0) return [];

return [{ json: {
  tenant: cfg.tenant,
  dryRun: true,
  ranAt: new Date().toISOString(),
  executionId: $execution.id,
  note: 'No writes were made. Set dryRun to false in Settings to apply.',
  candidatesScanned: planned.length,
  wouldFix: planned.filter(p => p.action === 'fix').length,
  wouldSkip: planned.filter(p => p.action === 'skip').length,
  wouldAlertOps: planned.filter(p => p.action === 'alert').length,
  plan: planned.map(p => ({
    shipment: p.number,
    order: p.orderNumbers,
    action: p.action,
    reason: p.reason,
    carrierNow: p.currentCarrier + ' / ' + p.currentService,
    carrierTarget: p.targetCarrier + ' / ' + p.targetService,
    linesToPersonalise: (p.optionsToCreate || []).map(o => o.sku + ' (line ' + o.line + ')'),
    existingValuesKept: p.keptExistingValues
  }))
}}];

